import type { Content } from './types.ts';

/**
 * Our own chronicle events for Sui, Tang, the Five Dynasties, Northern and Southern Song (581–1279); see
 * docs/data/content.md. Written from the standard histories (《隋书》《旧唐书》《新唐书》《旧五代史》《新五代史》《宋史》
 * 《辽史》《金史》《元史》), 《资治通鉴》 and the 统编版 textbooks; coordinates are the modern sites.
 *
 * Rows: [year, title zh, title en, site zh, site en, lon, lat, map change?, id override?]. Milestone ids are
 * `m-<dyn>-<year>`, landmark ids `l-<dyn>-<n>` in row order (append new rows at the end of a dynasty's list to keep ids).
 * The zh title's wording decides the event kind and model (jiangshan.ts kindOf / modelOf); its first clause (before
 * the first ，) is the short title, as is the en title's part before the first ;.
 */
type Row = [year: number, zh: string, en: string, siteZh: string, siteEn: string, lon: number, lat: number, map?: boolean, id?: string];

const milestones = (dyn: string, rows: Row[]): Content['milestones'] =>
  rows.map(([year, zh, en, sz, se, lon, lat, map, id]) => ({
    id: id ?? `m-${dyn}-${year}`, dyn, year, title: { zh, en }, site: { zh: sz, en: se }, lon, lat, ...(map ? { map: true } : {}),
  }));
const landmarks = (dyn: string, rows: Row[]): Content['landmarks'] =>
  rows.map(([year, zh, en, sz, se, lon, lat], i) => ({
    id: `l-${dyn}-${i + 1}`, dyn, year, title: { zh, en }, site: { zh: sz, en: se }, lon, lat,
  }));

