const LUOYANG: [string, string, number, number] = ['洛阳（今河南洛阳）', 'Luoyang (Henan)', 112.45, 34.62];
const BIANJING: [string, string, number, number] = ['东京开封府（今河南开封）', 'Kaifeng (Henan)', 114.31, 34.8];
const BIANZHOU: [string, string, number, number] = ['汴州（今河南开封）', 'Bianzhou (Kaifeng, Henan)', 114.31, 34.8];
const LINAN: [string, string, number, number] = ['临安（今浙江杭州）', 'Lin’an (Hangzhou, Zhejiang)', 120.16, 30.27];
const LUOXIE: [string, string, number, number] = ['逻些（今西藏拉萨）', 'Rasa (Lhasa, Tibet)', 91.13, 29.65];
const site = (s: [string, string, number, number]) => s;

const r = (year: number, zh: string, en: string, s: [string, string, number, number], map?: boolean, id?: string): Row =>
  [year, zh, en, s[0], s[1], s[2], s[3], map, id];

